1	// THE UPDATE RUNNER (#768) — the shell that makes the versioned flows actually run
2	// against a member. Everything it decides was decided elsewhere: the flows judge and
3	// write, `terminalFor` says what happens to the PR, `deliveryFor` says whether the PR
4	// this run opens is the member's to land. What lives here is the I/O none of them may
5	// carry — the clone, the branch, the commit, the push, the PR, and the hand-off.
6	//
7	// SAME SHAPE AS BASELINING, deliberately. That worker is the proven pattern for
8	// "converge a member from its own Actions run": clone canon fresh, run the CLONE's
9	// scripts as subprocesses rather than the mount's stale copies, deliver on a branch,
10	// and let the shared landing helper own every nuance of arming versus merging. A
11	// second, cleverer shape here would be a second set of the same bugs.
12	//
13	// IT NO LONGER ASKS WHICH MECHANISM SERVES THE REPO. There is one, and its only
14	// rival was deleted in #768 Phase 5, so the question had exactly one answer for
15	// every member that could ask it; the `maintenance` block that held it is gone
16	// (#1252) and `engine/served-by.mjs` is deprecated with it.
17	import { execFileSync } from 'node:child_process';
18	import { readFileSync, existsSync, mkdtempSync, writeFileSync } from 'node:fs';
19	import { join } from 'node:path';
20	import { tmpdir } from 'node:os';
21	import { pathToFileURL } from 'node:url';
22	import { removeTree } from '../../../../engine/remove-tree.mjs';
23	import {
24	  deliveryFor, pullCreateError, landDelivery, openDeliveredPull, disposeOpenPull, withTaskTrailer,
25	} from '../../../claudinite-tasks/shared-code/delivery.mjs';
26	import { settingsPath, SETTINGS_FILE } from '../../../../engine/settings-file.mjs';
27	
28	const CANON_URL = 'https://github.com/missingbulb/Claudinite.git'; // public — no token
29	const UPDATE_PREFIX = 'claudinite/update';
30	// What this worker stamps on everything it commits and merges (task-trailer.mjs).
31	const UPDATE_TASK_ID = 'claudinite-lifecycle/update';
32	const API = 'https://api.github.com';
33	
34	const git = (args, opts = {}) =>
35	  execFileSync('git', args, { encoding: 'utf8', stdio: ['ignore', 'pipe', 'pipe'], ...opts });
36	
37	async function gh(token, path, { method = 'GET', body } = {}) {
38	  const res = await fetch(`${API}${path}`, {
39	    method,
40	    headers: {
41	      authorization: `Bearer ${token}`,
42	      accept: 'application/vnd.github+json',
43	      'x-github-api-version': '2022-11-28',
44	      ...(body ? { 'content-type': 'application/json' } : {}),
45	    },
46	    body: body ? JSON.stringify(body) : undefined,
47	  });
48	  let json = null;
49	  try { json = await res.json(); } catch { /* empty body */ }
50	  return { status: res.status, json };
51	}
52	
53	// --- pure helpers (exported, unit-tested git-free) --------------------------
54	
55	// One branch per run, dated and seeded like baselining's: two runs on one day must
56	// not collide, and a name that carries its date is one a human can read a week later.
57	export const updateBranchName = (day, seed) => `${UPDATE_PREFIX}-${day}-${seed}`;
58	
59	// The line the LIVE CANARY rehearsal greps for. A rehearsal that converges nothing
60	// and exits 0 is worse than no gate at all — it reports a qualification that never
61	// happened — and that is not hypothetical: this exact gate went vacuous the day the
62	// canary flipped to `updates`, because the workflow drove the canary's baselining
63	// worker, which correctly stood down and exited 0 in zero seconds for weeks.
64	//
65	// So the rehearsal announces that it really ran, and the workflow fails when this
66	// line is absent. Any future path that skips the converge is caught by construction
67	// rather than by someone noticing a suspiciously fast green.
68	export const REHEARSAL_MARKER = 'claudinite-rehearsal: converged';
69	
70	// The PR title and body for a terminal. The body is what a human reads when the run
71	// stopped, so it says WHICH terminal fired and why in its first line — a PR that only
72	// says "an update ran" makes every reader re-derive the thing the run already knew.
73	//
74	// THE TITLE IS A SUMMARY, THE BODY IS THE DETAIL. A title that names every moved pack
75	// grows with the number a member declares, and a PR list is where that is least
76	// readable — so the packs collapse to a count and only the engine keeps its versions.
77	export function updatePullText(terminal, { engine, packs }) {
78	  const engineMoved = engine?.from !== engine?.to;
79	  const movedPacks = (packs?.plan ?? []).filter((p) => p.from !== p.to);
80	  const moved = [
81	    ...(engineMoved ? [`engine ${engine?.from ?? 'unstamped'} → ${engine?.to}`] : []),
82	    ...movedPacks.map((p) => `${p.id} ${p.from ?? 'unstamped'} → ${p.to}`),
83	  ];
84	  const summary = [
85	    ...(engineMoved ? [`engine ${engine?.from == null ? 'unstamped' : `v${engine.from}`} → v${engine?.to}`] : []),
86	    ...(movedPacks.length ? [`${movedPacks.length} pack${movedPacks.length === 1 ? '' : 's'} upgraded`] : []),
87	  ];
88	  const title = summary.length ? `Claudinite update: ${summary.join(' and ')}` : 'Claudinite update';
89	  const lines = [`**${terminal.action}** — ${terminal.why}`, ''];
90	  if (moved.length) lines.push('Versions moved by this run:', ...moved.map((m) => `- ${m}`), '');
91	  else lines.push('No version moved; this run converged the mount and changed nothing else.', '');
92	  if (terminal.action === 'needs-human') {
93	    lines.push('This PR stays open. Nothing merges on a non-green terminal — see the label.');
94	  } else if (terminal.action === 'apply-stage') {
95	    lines.push('The deterministic half is done. The agent stage applies the new rules to this repo\'s own content before anything merges.');
96	  }
97	  return { title, body: `${lines.join('\n')}\n` };
98	}
99	
100	// --- I/O shell (validated by the live pilot, not unit tests) ----------------
101	
102	export async function main() {
103	  const root = process.env.CLAUDINITE_REPO_ROOT || process.cwd();
104	  const repo = process.env.CLAUDINITE_REPO || process.env.GITHUB_REPOSITORY;
105	  const base = process.env.CLAUDINITE_DEFAULT_BRANCH || 'main';
106	  const token = process.env.GITHUB_TOKEN;
107	  const requestFile = process.env.CLAUDINITE_REQUEST_AGENT;
108	  // REHEARSAL MODE (the live canary): converge this repo against a NAMED canon ref,
109	  // report, and restore the working tree — no branch, no commit, no PR, and above
110	  // all no stamp. A stamped branch head would leave the canary pointing off trunk,
111	  // which is exactly what the next converge's anti-rewind guard refuses: a rehearsal
112	  // that wedges its own canary.
113	  const rehearsalRef = process.env.CLAUDINITE_CANON_REF || null;
114	  if (!repo) { console.error('update: no repo (CLAUDINITE_REPO/GITHUB_REPOSITORY)'); process.exit(1); }
115	  if (!token) { console.error('update: no GITHUB_TOKEN in env'); process.exit(1); }
116	
117	  // Either settings-file name, in the rename's read order: this worker is VENDORED,
118	  // so the copy running on a member may predate the record that renamed its own
119	  // file — and one that only knew the new name would report "nothing to update" on
120	  // every repo still carrying the old one.
121	  const settingsFile = settingsPath(root);
122	  if (!existsSync(settingsFile)) { console.log(`update: no ${SETTINGS_FILE} — nothing to update`); return; }
123	  const declaration = JSON.parse(readFileSync(settingsFile, 'utf8'));
124	
125	  // One override, one direction: a repo that asked for review gets its PR opened and
126	  // left; every other repo — the normal shape, the key absent — has it landed.
127	  const delivery = deliveryFor(declaration);
128	
129	  // DISPOSE OF THE INCUMBENT FIRST (#787). A cycle that could not land its PR — the
130	  // usual cause is a `pull_request` run parked at `action_required` while the
131	  // dispatched one goes green seconds after the wait gave up — leaves it open for
132	  // "the next run to dispose of". This is that disposal, and it must happen BEFORE
133	  // the converge for the reason the bug existed: a cycle that finds nothing to do
134	  // returns early, so disposal placed after the converge is unreachable on exactly
135	  // the quiet cycle that should perform it. A cycle that cannot clear the way does
136	  // not deliver on top of it — one update PR is alive at a time, or none.
137	  const open = rehearsalRef ? { json: [] } : await gh(token, `/repos/${repo}/pulls?state=open&per_page=100`);
138	  const incumbent = openDeliveredPull(open.json, UPDATE_PREFIX);
139	  if (incumbent) {
140	    const disposal = await disposeOpenPull({
141	      task: UPDATE_TASK_ID,
142	      token, repo, pr: incumbent, delivery, log: (s) => console.log(`update: ${s}`),
143	    }).catch((e) => { console.log(`update: disposing of PR #${incumbent.number} failed: ${e.message}`); return 'kept'; });
144	    if (disposal === 'kept') {
145	      console.log(`update: PR #${incumbent.number} still stands — this cycle cannot deliver on top of it`);
146	      return;
147	    }
148	    if (disposal === 'merged') {
149	      console.log(`update: landed PR #${incumbent.number}; main has moved past this checkout — next cycle converges from it`);
150	      return;
151	    }
152	  }
153	
154	  // The flows run from a FRESH CANON CLONE, never from this repo's mount: the mount is
155	  // the thing being replaced, and a flow executing its own stale copy is how a broken
156	  // update makes itself permanent.
157	  const tmp = mkdtempSync(join(tmpdir(), 'claudinite-canon-'));
158	  try {
159	    // A rehearsal names the ref it is qualifying; an ordinary cycle takes the
160	    // default branch, which is the only thing a member should ever converge onto.
161	    git(rehearsalRef
162	      ? ['clone', '--depth', '1', '--branch', rehearsalRef, CANON_URL, tmp]
163	      : ['clone', '--depth', '1', CANON_URL, tmp]);
164	    const load = async (rel) => import(pathToFileURL(join(tmp, rel)).href);
165	    const { engineUpdate } = await load('packs/claudinite-lifecycle/updates/engine-update.mjs');
166	    const { packUpdate } = await load('packs/claudinite-lifecycle/updates/pack-update.mjs');
167	    const { terminalFor } = await load('packs/claudinite-lifecycle/updates/terminals.mjs');
168	
169	    // ENGINE FIRST, always: a pack declares the minimum engine it runs on, and the
170	    // pack flow enforces that against what this repo HAS. Running packs first would
171	    // check every pack against yesterday's engine and block updates that the very
172	    // next step would have made legal.
173	    const engine = await engineUpdate(root, { fullName: repo, delivery, selfTestRun: undefined });
174	    console.log(`update: engine — ${engine.status}: ${engine.detail}`);
175	    let packs = null;
176	    if (engine.status !== 'needs-human') {
177	      packs = await packUpdate(root, { fullName: repo, delivery, selfTestRun: undefined });
178	      console.log(`update: packs — ${packs.status}: ${packs.detail}`);
179	    }
180	
181	    // The engine's terminal wins when it stopped the run: nothing downstream of a
182	    // refused engine update is trustworthy, including a pack flow that never ran.
183	    const outcome = engine.status === 'needs-human' ? engine : packs;
184	    const terminal = terminalFor(outcome);
185	
186	    // A REHEARSAL STOPS HERE. It has the only answer it was asked for — does this
187	    // canon ref converge this member and leave it green — so it says so and puts the
188	    // tree back exactly as it found it. Restoring is not tidiness: an uncommitted
189	    // converge left behind would be picked up by the canary's own next cycle as if a
190	    // human had written it.
191	    if (rehearsalRef) {
192	      git(['-C', root, 'checkout', '--', '.']);
193	      git(['-C', root, 'clean', '-fd']);
194	      if (terminal.action === 'needs-human') {
195	        console.error(`update: rehearsing ${rehearsalRef} FAILED — ${terminal.why}`);
196	        process.exit(1);
197	      }
198	      console.log(`${REHEARSAL_MARKER} ${repo} against ${rehearsalRef} — ${terminal.action}: ${terminal.why}`);
199	      return;
200	    }
201	
202	    // AN APPLY STAGE IS NOT "NOTHING CHANGED" (#1545). A run that withheld a workflow
203	    // file leaves the pack unstamped, precisely so the record stays in range — so on a
204	    // cycle that re-stages content the branch already carries, the tree can be clean
205	    // while a delivery is still owed. Returning here would skip the PR, and the
206	    // apply-stage request is written below it, so nobody would ever be asked to deliver:
207	    // the silent loss this whole fix exists to end, one step further along. The empty
208	    // commit is the point — the apply stage's own move is what fills the PR.
209	    const changed = git(['-C', root, 'status', '--porcelain']).trim();
210	    if (!changed && terminal.action !== 'needs-human' && terminal.action !== 'apply-stage') {
211	      console.log('update: nothing changed — no branch, no PR');
212	      return;
213	    }
214	
215	    const day = new Date().toISOString().slice(0, 10);
216	    const seed = Math.random().toString(36).slice(2, 8);
217	    const branch = updateBranchName(day, seed);
218	    git(['-C', root, 'checkout', '-B', branch]);
219	    git(['-C', root, 'add', '-A']);
220	    const staged = git(['-C', root, 'diff', '--cached', '--name-only']).split('\n').filter(Boolean);
221	    const { title, body } = updatePullText(terminal, { engine, packs });
222	    git(['-C', root, '-c', 'user.name=claudinite[bot]', '-c', 'user.email=claudinite@users.noreply.github.com',
223	      // The trailer is what classifies this converge as machinery to every
224	      // movement-gated task: the mount refreshing is not the project moving.
225	      'commit', ...(staged.length ? [] : ['--allow-empty']), '-m', withTaskTrailer(title, UPDATE_TASK_ID)]);
226	    git(['-C', root, 'push', '--force', `https://x-access-token:${token}@github.com/${repo}.git`, `HEAD:refs/heads/${branch}`]);
227	
228	    const created = await gh(token, `/repos/${repo}/pulls`, { method: 'POST', body: { head: branch, base, title, body } });
229	    const failure = pullCreateError(created.status, created.json);
230	    if (failure) throw new Error(`could not open the update PR for ${branch}: ${failure}`);
231	    const pr = created.json;
232	    console.log(`update: opened PR #${pr.number} on ${branch} (${terminal.action})`);
233	
234	    // The terminal, acted on. Only one action merges, and it is the one the flow
235	    // already judged green — everything else leaves the PR standing, labelled or
236	    // handed to the agent stage.
237	    if (terminal.action === 'merge') {
238	      await landDelivery({ token, repo, base, pr, delivery, task: UPDATE_TASK_ID });
239	    } else if (terminal.action === 'needs-human') {
240	      await gh(token, `/repos/${repo}/issues/${pr.number}/labels`, { method: 'POST', body: { labels: [terminal.label] } });
241	      console.error(`update: left PR #${pr.number} open and labelled ${terminal.label} — ${terminal.why}`);
242	      // NON-ZERO, so the work item lands in `needs-human` rather than closing
243	      // `task:done`. This terminal means the converge DID NOT DELIVER — the PR
244	      // is parked awaiting a person — and a run that delivered nothing must not
245	      // report success. Exiting 0 here is what hid #939 for five days: every
246	      // member's nightly update closed `task:done` while its PR sat parked, so
247	      // the whole fleet was frozen and every signal said healthy. This is the
248	      // "reserve non-zero for genuine breakage" rule's genuine breakage: the
249	      // member is not converging and nothing else will say so.
250	      process.exitCode = 1;
251	    } else if (terminal.action === 'apply-stage' && requestFile) {
252	      writeFileSync(requestFile, `${JSON.stringify({
253	        marker: 'agent-requested',
254	        delivered: { branch, pr: pr.number, merged: false },
255	        reason: { code: 'apply-stage', detail: terminal.why },
256	      })}\n`);
257	      console.log(`update: requested the apply stage — ${terminal.why}`);
258	    }
259	  } finally {
260	    removeTree(tmp);
261	  }
262	}
263	
264	if (process.argv[1] && import.meta.url === pathToFileURL(process.argv[1]).href) {
265	  main().catch((e) => { console.error(`update failed: ${e.message}`); process.exit(1); });
266	}
