// THE UPDATE RUNNER (#768) — the shell that makes the versioned flows actually run
// against a member. Everything it decides was decided elsewhere: the flows judge and
// write, `terminalFor` says what happens to the PR, `deliveryFor` says whether the PR
// this run opens is the member's to land. What lives here is the I/O none of them may
// carry — the clone, the branch, the commit, the push, the PR, and the hand-off.
//
// SAME SHAPE AS BASELINING, deliberately. That worker is the proven pattern for
// "converge a member from its own Actions run": clone canon fresh, run the CLONE's
// scripts as subprocesses rather than the mount's stale copies, deliver on a branch,
// and let the shared landing helper own every nuance of arming versus merging. A
// second, cleverer shape here would be a second set of the same bugs.
//
// IT NO LONGER ASKS WHICH MECHANISM SERVES THE REPO. There is one, and its only
// rival was deleted in #768 Phase 5, so the question had exactly one answer for
// every member that could ask it; the `maintenance` block that held it is gone
// (#1252) and `engine/served-by.mjs` is deprecated with it.
import { execFileSync } from 'node:child_process';
import { readFileSync, existsSync, mkdtempSync, writeFileSync } from 'node:fs';
import { join } from 'node:path';
import { tmpdir } from 'node:os';
import { pathToFileURL } from 'node:url';
import { removeTree } from '../../../../engine/remove-tree.mjs';
import {
  deliveryFor, pullCreateError, landDelivery, openDeliveredPull, disposeOpenPull, withTaskTrailer,
} from '../../../claudinite-tasks/shared-code/delivery.mjs';
import { settingsPath, SETTINGS_FILE } from '../../../../engine/settings-file.mjs';

const CANON_URL = 'https://github.com/missingbulb/Claudinite.git'; // public — no token
const UPDATE_PREFIX = 'claudinite/update';
// What this worker stamps on everything it commits and merges (task-trailer.mjs).
const UPDATE_TASK_ID = 'claudinite-lifecycle/update';
const API = 'https://api.github.com';

const git = (args, opts = {}) =>
  execFileSync('git', args, { encoding: 'utf8', stdio: ['ignore', 'pipe', 'pipe'], ...opts });

async function gh(token, path, { method = 'GET', body } = {}) {
  const res = await fetch(`${API}${path}`, {
    method,
    headers: {
      authorization: `Bearer ${token}`,
      accept: 'application/vnd.github+json',
      'x-github-api-version': '2022-11-28',
      ...(body ? { 'content-type': 'application/json' } : {}),
    },
    body: body ? JSON.stringify(body) : undefined,
  });
  let json = null;
  try { json = await res.json(); } catch { /* empty body */ }
  return { status: res.status, json };
}

// --- pure helpers (exported, unit-tested git-free) --------------------------

// One branch per run, dated and seeded like baselining's: two runs on one day must
// not collide, and a name that carries its date is one a human can read a week later.
export const updateBranchName = (day, seed) => `${UPDATE_PREFIX}-${day}-${seed}`;

// The line the LIVE CANARY rehearsal greps for. A rehearsal that converges nothing
// and exits 0 is worse than no gate at all — it reports a qualification that never
// happened — and that is not hypothetical: this exact gate went vacuous the day the
// canary flipped to `updates`, because the workflow drove the canary's baselining
// worker, which correctly stood down and exited 0 in zero seconds for weeks.
//
// So the rehearsal announces that it really ran, and the workflow fails when this
// line is absent. Any future path that skips the converge is caught by construction
// rather than by someone noticing a suspiciously fast green.
export const REHEARSAL_MARKER = 'claudinite-rehearsal: converged';

// The PR title and body for a terminal. The body is what a human reads when the run
// stopped, so it says WHICH terminal fired and why in its first line — a PR that only
// says "an update ran" makes every reader re-derive the thing the run already knew.
//
// THE TITLE IS A SUMMARY, THE BODY IS THE DETAIL. A title that names every moved pack
// grows with the number a member declares, and a PR list is where that is least
// readable — so the packs collapse to a count and only the engine keeps its versions.
export function updatePullText(terminal, { engine, packs }) {
  const engineMoved = engine?.from !== engine?.to;
  const movedPacks = (packs?.plan ?? []).filter((p) => p.from !== p.to);
  const moved = [
    ...(engineMoved ? [`engine ${engine?.from ?? 'unstamped'} → ${engine?.to}`] : []),
    ...movedPacks.map((p) => `${p.id} ${p.from ?? 'unstamped'} → ${p.to}`),
  ];
  const summary = [
    ...(engineMoved ? [`engine ${engine?.from == null ? 'unstamped' : `v${engine.from}`} → v${engine?.to}`] : []),
    ...(movedPacks.length ? [`${movedPacks.length} pack${movedPacks.length === 1 ? '' : 's'} upgraded`] : []),
  ];
  const title = summary.length ? `Claudinite update: ${summary.join(' and ')}` : 'Claudinite update';
  const lines = [`**${terminal.action}** — ${terminal.why}`, ''];
  if (moved.length) lines.push('Versions moved by this run:', ...moved.map((m) => `- ${m}`), '');
  else lines.push('No version moved; this run converged the mount and changed nothing else.', '');
  if (terminal.action === 'needs-human') {
    lines.push('This PR stays open. Nothing merges on a non-green terminal — see the label.');
  } else if (terminal.action === 'apply-stage') {
    lines.push('The deterministic half is done. The agent stage applies the new rules to this repo\'s own content before anything merges.');
  }
  return { title, body: `${lines.join('\n')}\n` };
}

// --- I/O shell (validated by the live pilot, not unit tests) ----------------

export async function main() {
  const root = process.env.CLAUDINITE_REPO_ROOT || process.cwd();
  const repo = process.env.CLAUDINITE_REPO || process.env.GITHUB_REPOSITORY;
  const base = process.env.CLAUDINITE_DEFAULT_BRANCH || 'main';
  const token = process.env.GITHUB_TOKEN;
  const requestFile = process.env.CLAUDINITE_REQUEST_AGENT;
  // REHEARSAL MODE (the live canary): converge this repo against a NAMED canon ref,
  // report, and restore the working tree — no branch, no commit, no PR, and above
  // all no stamp. A stamped branch head would leave the canary pointing off trunk,
  // which is exactly what the next converge's anti-rewind guard refuses: a rehearsal
  // that wedges its own canary.
  const rehearsalRef = process.env.CLAUDINITE_CANON_REF || null;
  if (!repo) { console.error('update: no repo (CLAUDINITE_REPO/GITHUB_REPOSITORY)'); process.exit(1); }
  if (!token) { console.error('update: no GITHUB_TOKEN in env'); process.exit(1); }

  // Either settings-file name, in the rename's read order: this worker is VENDORED,
  // so the copy running on a member may predate the record that renamed its own
  // file — and one that only knew the new name would report "nothing to update" on
  // every repo still carrying the old one.
  const settingsFile = settingsPath(root);
  if (!existsSync(settingsFile)) { console.log(`update: no ${SETTINGS_FILE} — nothing to update`); return; }
  const declaration = JSON.parse(readFileSync(settingsFile, 'utf8'));

  // One override, one direction: a repo that asked for review gets its PR opened and
  // left; every other repo — the normal shape, the key absent — has it landed.
  const delivery = deliveryFor(declaration);

  // DISPOSE OF THE INCUMBENT FIRST (#787). A cycle that could not land its PR — the
  // usual cause is a `pull_request` run parked at `action_required` while the
  // dispatched one goes green seconds after the wait gave up — leaves it open for
  // "the next run to dispose of". This is that disposal, and it must happen BEFORE
  // the converge for the reason the bug existed: a cycle that finds nothing to do
  // returns early, so disposal placed after the converge is unreachable on exactly
  // the quiet cycle that should perform it. A cycle that cannot clear the way does
  // not deliver on top of it — one update PR is alive at a time, or none.
  const open = rehearsalRef ? { json: [] } : await gh(token, `/repos/${repo}/pulls?state=open&per_page=100`);
  const incumbent = openDeliveredPull(open.json, UPDATE_PREFIX);
  if (incumbent) {
    const disposal = await disposeOpenPull({
      task: UPDATE_TASK_ID,
      token, repo, pr: incumbent, delivery, log: (s) => console.log(`update: ${s}`),
    }).catch((e) => { console.log(`update: disposing of PR #${incumbent.number} failed: ${e.message}`); return 'kept'; });
    if (disposal === 'kept') {
      console.log(`update: PR #${incumbent.number} still stands — this cycle cannot deliver on top of it`);
      return;
    }
    if (disposal === 'merged') {
      console.log(`update: landed PR #${incumbent.number}; main has moved past this checkout — next cycle converges from it`);
      return;
    }
  }

  // The flows run from a FRESH CANON CLONE, never from this repo's mount: the mount is
  // the thing being replaced, and a flow executing its own stale copy is how a broken
  // update makes itself permanent.
  const tmp = mkdtempSync(join(tmpdir(), 'claudinite-canon-'));
  try {
    // A rehearsal names the ref it is qualifying; an ordinary cycle takes the
    // default branch, which is the only thing a member should ever converge onto.
    git(rehearsalRef
      ? ['clone', '--depth', '1', '--branch', rehearsalRef, CANON_URL, tmp]
      : ['clone', '--depth', '1', CANON_URL, tmp]);
    const load = async (rel) => import(pathToFileURL(join(tmp, rel)).href);
    const { engineUpdate } = await load('packs/claudinite-lifecycle/updates/engine-update.mjs');
    const { packUpdate } = await load('packs/claudinite-lifecycle/updates/pack-update.mjs');
    const { terminalFor } = await load('packs/claudinite-lifecycle/updates/terminals.mjs');

    // ENGINE FIRST, always: a pack declares the minimum engine it runs on, and the
    // pack flow enforces that against what this repo HAS. Running packs first would
    // check every pack against yesterday's engine and block updates that the very
    // next step would have made legal.
    const engine = await engineUpdate(root, { fullName: repo, delivery, selfTestRun: undefined });
    console.log(`update: engine — ${engine.status}: ${engine.detail}`);
    let packs = null;
    if (engine.status !== 'needs-human') {
      packs = await packUpdate(root, { fullName: repo, delivery, selfTestRun: undefined });
      console.log(`update: packs — ${packs.status}: ${packs.detail}`);
    }

    // The engine's terminal wins when it stopped the run: nothing downstream of a
    // refused engine update is trustworthy, including a pack flow that never ran.
    const outcome = engine.status === 'needs-human' ? engine : packs;
    const terminal = terminalFor(outcome);

    // A REHEARSAL STOPS HERE. It has the only answer it was asked for — does this
    // canon ref converge this member and leave it green — so it says so and puts the
    // tree back exactly as it found it. Restoring is not tidiness: an uncommitted
    // converge left behind would be picked up by the canary's own next cycle as if a
    // human had written it.
    if (rehearsalRef) {
      git(['-C', root, 'checkout', '--', '.']);
      git(['-C', root, 'clean', '-fd']);
      if (terminal.action === 'needs-human') {
        console.error(`update: rehearsing ${rehearsalRef} FAILED — ${terminal.why}`);
        process.exit(1);
      }
      console.log(`${REHEARSAL_MARKER} ${repo} against ${rehearsalRef} — ${terminal.action}: ${terminal.why}`);
      return;
    }

    // AN APPLY STAGE IS NOT "NOTHING CHANGED" (#1545). A run that withheld a workflow
    // file leaves the pack unstamped, precisely so the record stays in range — so on a
    // cycle that re-stages content the branch already carries, the tree can be clean
    // while a delivery is still owed. Returning here would skip the PR, and the
    // apply-stage request is written below it, so nobody would ever be asked to deliver:
    // the silent loss this whole fix exists to end, one step further along. The empty
    // commit is the point — the apply stage's own move is what fills the PR.
    const changed = git(['-C', root, 'status', '--porcelain']).trim();
    if (!changed && terminal.action !== 'needs-human' && terminal.action !== 'apply-stage') {
      console.log('update: nothing changed — no branch, no PR');
      return;
    }

    const day = new Date().toISOString().slice(0, 10);
    const seed = Math.random().toString(36).slice(2, 8);
    const branch = updateBranchName(day, seed);
    git(['-C', root, 'checkout', '-B', branch]);
    git(['-C', root, 'add', '-A']);
    const staged = git(['-C', root, 'diff', '--cached', '--name-only']).split('\n').filter(Boolean);
    const { title, body } = updatePullText(terminal, { engine, packs });
    git(['-C', root, '-c', 'user.name=claudinite[bot]', '-c', 'user.email=claudinite@users.noreply.github.com',
      // The trailer is what classifies this converge as machinery to every
      // movement-gated task: the mount refreshing is not the project moving.
      'commit', ...(staged.length ? [] : ['--allow-empty']), '-m', withTaskTrailer(title, UPDATE_TASK_ID)]);
    git(['-C', root, 'push', '--force', `https://x-access-token:${token}@github.com/${repo}.git`, `HEAD:refs/heads/${branch}`]);

    const created = await gh(token, `/repos/${repo}/pulls`, { method: 'POST', body: { head: branch, base, title, body } });
    const failure = pullCreateError(created.status, created.json);
    if (failure) throw new Error(`could not open the update PR for ${branch}: ${failure}`);
    const pr = created.json;
    console.log(`update: opened PR #${pr.number} on ${branch} (${terminal.action})`);

    // The terminal, acted on. Only one action merges, and it is the one the flow
    // already judged green — everything else leaves the PR standing, labelled or
    // handed to the agent stage.
    if (terminal.action === 'merge') {
      await landDelivery({ token, repo, base, pr, delivery, task: UPDATE_TASK_ID });
    } else if (terminal.action === 'needs-human') {
      await gh(token, `/repos/${repo}/issues/${pr.number}/labels`, { method: 'POST', body: { labels: [terminal.label] } });
      console.error(`update: left PR #${pr.number} open and labelled ${terminal.label} — ${terminal.why}`);
      // NON-ZERO, so the work item lands in `needs-human` rather than closing
      // `task:done`. This terminal means the converge DID NOT DELIVER — the PR
      // is parked awaiting a person — and a run that delivered nothing must not
      // report success. Exiting 0 here is what hid #939 for five days: every
      // member's nightly update closed `task:done` while its PR sat parked, so
      // the whole fleet was frozen and every signal said healthy. This is the
      // "reserve non-zero for genuine breakage" rule's genuine breakage: the
      // member is not converging and nothing else will say so.
      process.exitCode = 1;
    } else if (terminal.action === 'apply-stage' && requestFile) {
      writeFileSync(requestFile, `${JSON.stringify({
        marker: 'agent-requested',
        delivered: { branch, pr: pr.number, merged: false },
        reason: { code: 'apply-stage', detail: terminal.why },
      })}\n`);
      console.log(`update: requested the apply stage — ${terminal.why}`);
    }
  } finally {
    removeTree(tmp);
  }
}

if (process.argv[1] && import.meta.url === pathToFileURL(process.argv[1]).href) {
  main().catch((e) => { console.error(`update failed: ${e.message}`); process.exit(1); });
}

// A member's own task declarations become data (#1633): every
// `.claudinite/local/packs/<pack>/tasks/<name>/task.mjs` is converted to a
// `task.json` pointing at the task schema, and the module is deleted.
//
// THE WRITE IS THE ENGINE'S. `taskDeclarationsToJson: true` names the registry's
// named codemod (engine/migrations/registry.mjs, `applyTaskDeclarationConversion`),
// which runs the same converter the CLI does. A record cannot carry it: the JSON is
// the module's evaluated export, which no textual rewrite produces.
//
// GATED ON THE MOUNT, BY CONTENT. Converting is only safe once the member's
// vendored `claudinite-tasks` reads `task.json` — this pack's discover goes
// through `task-declaration.mjs` from the version this record lands with, and an
// older mount would see a folder with no `task.mjs` and silently run nothing.
// The two lanes deliver on their own cadences, so `appliesTo` probes the mounted
// pack for that module rather than trusting the stamp; an unreadable mount reads
// as "not capable" and the record stays inert. The canon runs the same probe
// against its own tree (two-root form).
//
// IDEMPOTENT by construction: a folder with no `task.mjs` is nothing to convert.
//
// THE APPLY STAGE WRITES THE DESCRIPTIONS. A converted declaration has every field
// its module had and no `description`, because a description is judgment — what
// the task does, or why it exists, in the words a reader of the pack wants — and
// the code cannot write one. The module's comments went into the task's README
// (the converter's doing), so the session has the author's own words to work from.
// The stage runs once per member, on the update that delivers this record; on a
// member with no local tasks it finds nothing to write and ends.
const READER = 'packs/claudinite-tasks/task-declaration-text.mjs';
const mountReadsJson = async (read) => {
  const text = (await read(`.claudinite/shared/${READER}`)) ?? (await read(READER));
  return Boolean(text) && text.includes("'task.json'");
};

export default {
  id: 'task-declarations-json',
  landed: '2026-09-02',
  version: '60903.3',
  summary: 'a member\'s local-pack task.mjs declarations are converted to task.json, the data form the engine now reads (#1633)',

  appliesTo: mountReadsJson,
  taskDeclarationsToJson: true,

  applyStage: {
    why: 'each converted local-pack task declaration needs a description only a reader of the task can write',
    instructions: [
      'The deterministic half converted every `.claudinite/local/packs/<pack>/tasks/<name>/task.mjs`',
      'in this repo to a `task.json`, moving the module\'s comments into that task\'s `README.md`',
      'under "Why the declaration reads as it does". What it could not write is the',
      '`description` field. For every `task.json` under `.claudinite/local/packs/` that has',
      'no `description`, add one: up to fifty words on what the task does, or why it exists,',
      'read from the task\'s README, its `task.md` if it has one, and its worker. It must not',
      'restate what the other fields already say — never the cadence, the conditions, the',
      'automerge policy, or where the files live. Place it right after `id`, keep the file\'s',
      'other keys and its indentation as they are, and do not edit the vendored mount under',
      '`.claudinite/shared/`. A task.json that already carries a description is left alone.',
      'If no local task.json lacks one, there is nothing to do here.',
    ].join('\n'),
  },

  // The telemetry hook cannot list directories, and the fact this record retires
  // — a `task.mjs` under the member's local packs — is only visible by listing.
  // The fleet-visible signal is the shape check's advisory on every remaining
  // module (task-declaration-shape); the cleanup that drops the module reader is
  // gated on that advisory firing nowhere (#1633).
  legacyPresent: async () => false,
};

content.content:
1	// THE TERMINAL TRANSITION, IN CODE (#892; tasks-dispatch DESIGN §6.5, §15.18).
2	// A work-item session ends by performing five ordered side effects — comment,
3	// drop `task:agent`, add the outcome label, carry the execution record, close
4	// with the right state reason — on the item it holds, and nothing else: a
5	// converge never writes to another work item (§15.19, reversed by §15.31 /
6	// #1373). Releasing a dependent a close may have freed is the scheduler run's
7	// job alone. Asking a session to perform these effects from prose is asking for
8	// it at the moment its context is fullest and the remaining work looks like
9	// formality; both of the first two live agentic runs got part of it wrong,
10	// silently, in different ways.
11	//
12	// THIS FILE RUNS IN ONE PLACE: INSIDE A WORK-ITEM SESSION. `queue/instructions.md`
13	// step 6 is its only caller — no workflow invokes it, no module imports it. The
14	// Actions side converges through `executor.mjs`, which owns that path entirely.
15	//
16	// SO EVERY LINE HERE ASSUMES MCP, AND NOTHING HERE MAY REACH THE NETWORK. A session
17	// holds its GitHub access through its own tools; a subprocess it spawns has no route
18	// to them and none to the REST API. This file therefore PLANS a transition and
19	// PRINTS it addressed to those tools — it never performs one. Printing the calls is
20	// the successful outcome, on stdout, exit 0. That is not a fallback: it is the only
21	// path, and it must never read as a failure. A REST executor lived here once and did
22	// (#1491) — a session met its `console.error` before it met the path written for it,
23	// reported that it could not converge, and left the item to the janitor's 3h leash,
24	// which parks a finished run as a human decision. Five sampled items across five
25	// repos were exactly that.
26	//
27	// The split is the same one the executor already draws: THE SESSION SUPPLIES THE
28	// JUDGMENT — which outcome, and the prose of what happened — and the CODE decides
29	// every step of the transition. A session that stops early now leaves an item that
30	// is visibly unconverged, rather than one that looks finished and is not.
31	//
32	// Usage — the item is handed in, because this process cannot read it:
33	//   node converge-item.mjs --issue <n> --outcome <done|approval|action|decision|failure>
34	//                          --summary <text> [--pr <n>]
35	//                          --repo <owner/name> --item-file <path to the issue as JSON>
36	
37	import { readFile } from 'node:fs/promises';
38	import { pathToFileURL } from 'node:url';
39	import { renderTaskExec } from '../run-record.mjs';
40	import {
41	  AGENT, TASK_DONE, STATUS_RUNNING_AGENT, isStatus, machineBlockOf,
42	  NEEDS_HUMAN_ACTION, NEEDS_HUMAN_APPROVAL, NEEDS_HUMAN_DECISION, NEEDS_HUMAN_FAILURE,
43	  QUEUED_LABEL, IN_REVIEW_LABEL, ORIGIN_LABELS, hasLabel,
44	  parseWorkItemTitle, parseWorkItemBody, spellingsOf, labelNames,
45	  editItemBody, withEndsWhen,
46	} from './work-item.mjs';
47	
48	// What a session may claim, and what each one means for the item. `record` is the
49	// execution-record status, and `null` means no record: an approval park is a run
50	// that SUCCEEDED and left a PR, which the record vocabulary has no word for, and
51	// a fifth status would be stored data every decoder in the fleet must learn.
52	export const OUTCOMES = Object.freeze({
53	  done: { label: TASK_DONE, closes: true, stateReason: 'completed', record: 'success' },
54	  approval: { label: NEEDS_HUMAN_APPROVAL, closes: false, record: null },
55	  action: { label: NEEDS_HUMAN_ACTION, closes: false, record: 'failed' },
56	  decision: { label: NEEDS_HUMAN_DECISION, closes: false, record: 'failed' },
57	  failure: { label: NEEDS_HUMAN_FAILURE, closes: false, record: 'failed' },
58	});
59	
60	export function parseArgs(argv) {
61	  const args = {};
62	  for (let n = 0; n < argv.length; n += 1) {
63	    const m = /^--([a-z-]+)$/.exec(argv[n]);
64	    if (m) { args[m[1]] = argv[n + 1] ?? ''; n += 1; }
65	  }
66	  const issue = Number(args.issue);
67	  if (!Number.isInteger(issue) || issue <= 0) return { error: '--issue must be the work item\'s issue number' };
68	  if (!OUTCOMES[args.outcome]) {
69	    return { error: `--outcome must be one of ${Object.keys(OUTCOMES).join(', ')}, got ${JSON.stringify(args.outcome ?? null)}` };
70	  }
71	  if (!String(args.summary ?? '').trim()) return { error: '--summary must say what happened; it is the item\'s only durable account' };
72	  if (args.outcome === 'approval' && !args.pr) {
73	    return { error: '--pr must name the pull request an approval park is waiting on — a park nobody can act on is not a park' };
74	  }
75	  return {
76	    issue, outcome: args.outcome, summary: args.summary, pr: args.pr ? Number(args.pr) : null,
77	    repo: args.repo || null, itemFile: args['item-file'] || null,
78	  };
79	}
80	
81	// Why an item may NOT be converged by this call. Refusing loudly beats writing a
82	// terminal state onto the wrong issue: this runs from a session, whose whole
83	// notion of which item it holds came from an untrusted fire payload.
84	export function refusal(item, issue) {
85	  if (!item) return `#${issue} could not be read`;
86	  // A marked issue IS its own item (DESIGN §16.1), so the title test cannot be the
87	  // membership test any more: what says this is one is the machine block adoption
88	  // wrote — never the body's first line, which on a marked issue is a person's prose.
89	  //
90	  // THREE SIGNALS, ANY ONE SUFFICIENT. A membership test gated on the single artifact
91	  // it exists to validate refuses exactly the items that artifact is missing from: an
92	  // issue adopted before the block delimiters existed carries its fields bare, and was
93	  // refused here into a by-hand convergence that dropped half the transition
94	  // (missingbulb/Shepherd#360). The origin label is the independent one — carried for
95	  // life, and platform-write-gated like the block was.
96	  const marked = ORIGIN_LABELS.some((name) => hasLabel(item, name));
97	  if (!parseWorkItemTitle(item.title ?? '') && machineBlockOf(item.body ?? '') === null && !marked) {
98	    return `#${issue} is not a Claudinite work item`;
99	  }
100	  if (item.state !== 'open') return `#${issue} is already closed — it was converged once already`;
101	  if (!isStatus(item, STATUS_RUNNING_AGENT)) {
102	    return `#${issue} is not with an agent (\`${AGENT}\`) — this session does not hold it, so it is not this session's to converge`;
103	  }
104	  return null;
105	}
106	
107	// The record line for this item, or null where the vocabulary has no true answer.
108	export const recordLine = (item, status) => {
109	  const parsed = parseWorkItemTitle(item.title);
110	  return status && parsed
111	    ? renderTaskExec({ pack: parsed.pack, task: parsed.task, slotId: `#${item.number}`, status })
112	    : null;
113	};
114	
115	// The comment one converge writes: the session's account, then the record, so a
116	// reader and a parser both find what they came for in one place.
117	export function convergeComment(item, { summary, pr, record }) {
118	  const rec = recordLine(item, record);
119	  const line = rec ? `\n\n\`\`\`\n${rec}\n\`\`\`` : '';
120	  const waiting = pr ? `\n\nWaiting on a person: merge or close #${pr}, then close this item.` : '';
121	  return `${summary.trim()}${waiting}${line}`;
122	}
123	
124	// THE TRANSITION AS DATA (#1374). The side effects were a straight line of
125	// `await api.…` calls, which silently made REST the only way to perform them —
126	// and the sessions `invoke.mjs` hands work to have no REST route to their own
127	// repository, so the last step of every agentic run was the one step that
128	// environment could not take.
129	//
130	// So the sequence is planned as OPS and executed by whoever can. The planner is
131	// the single source of what a convergence IS; the executors differ only in
132	// transport. The session still supplies nothing but the judgment.
133	//
134	// Removes are granular and unconditional — every spelling of the status being
135	// left, not only the ones this snapshot shows (apply-status.mjs's rule: a member's
136	// items outlive its converges, so an item may wear an older engine's spelling).
137	export function convergeOps(item, plan) {
138	  const spec = OUTCOMES[plan.outcome];
139	  const ops = [{ kind: 'comment', issue: item.number, body: convergeComment(item, { ...plan, record: spec.record }) }];
140	
141	  // The record goes to BOTH sinks, and neither is redundant: the comment above is
142	  // the durable one (Actions logs expire, the item does not), while this printed
143	  // copy lands in the session transcript, which is what the usage fold reads for
144	  // the task-status census.
145	  const rec = recordLine(item, spec.record);
146	  if (rec) ops.push({ kind: 'record', line: rec });
147	
148	  for (const label of spellingsOf(STATUS_RUNNING_AGENT)) {
149	    ops.push({ kind: 'removeLabel', issue: item.number, name: label });
150	  }
151	  // ONE label, on both paths: the outcome IS the status. A park in particular is
152	  // never a pair, so nothing can be half-applied (#1385).
153	  ops.push({ kind: 'addLabel', issue: item.number, name: spec.label });
154	
155	  // THE PARK'S END CONDITION (#1468). The comment above already tells a person to
156	  // merge or close the pull request; this says the same thing where the janitor can
157	  // read it, so the item ends when that happens instead of waiting for someone to
158	  // notice it already did. Every park that names one gets it, not only `approval`.
159	  if (!spec.closes && plan.pr) {
160	    ops.push({ kind: 'setBody', issue: item.number, body: editItemBody(item.body, (m) => withEndsWhen(m, plan.pr)) });
161	  }
162	
163	  if (spec.closes) {
164	    // A DONE TERMINAL CLOSES THE ISSUE IT STANDS ON, marked or filed (#1489,
165	    // reversing §16.1/§16.5's "never a marked issue"). `done` is the one outcome
166	    // that means nothing is left for anyone to act on, so an issue left open under
167	    // it asks its author to come and agree with what the run already settled. Every
168	    // other outcome parks, and a park leaves the issue open to be waited on.
169	    ops.push({ kind: 'close', issue: item.number, stateReason: spec.stateReason });
170	    return ops;
171	  }
172	
173	  // A REQUEST ITEM WRITES BACK TO ITS ISSUE, on the one end that is its business
174	  // (§16.5). Only the approval park: a failure deliberately writes nothing and
175	  // leaves `claude-queued` standing, because re-arming work that writes code is a
176	  // person's decision and that standing label is what stops the next scheduler run
177	  // queueing a second run of the same request. Only a LEGACY shadow item writes
178	  // back to a different issue.
179	  const { request } = parseWorkItemBody(item.body ?? '');
180	  if (request && request !== item.number && plan.outcome === 'approval') {
181	    ops.push({ kind: 'comment', issue: request, body: `A pull request for this is open and waiting on you: #${plan.pr}. Merge or close it.` });
182	    ops.push({ kind: 'removeLabel', issue: request, name: QUEUED_LABEL });
183	    ops.push({ kind: 'addLabel', issue: request, name: IN_REVIEW_LABEL });
184	  }
185	  return ops;
186	}
187	
188	// THE SESSION EXECUTOR'S SCRIPT. Same ops, addressed to the GitHub tools a session
189	// does have. Two differences forced by that surface, both handled here rather than
190	// left to the session to work out:
191	//
192	//  - THERE IS NO GRANULAR LABEL WRITE. `issue_write` replaces the whole set, so the
193	//    granular removes and adds are folded into the FINAL set here, computed from the
194	//    labels this item was read with. Everything not a status label is carried through.
195	//  - THE RECORD IS PRINTED BY THE SESSION, which is where it has to be anyway: the
196	//    usage fold reads the census out of the session transcript.
197	export function sessionScript(item, plan, repo) {
198	  const [owner, name] = String(repo).split('/');
199	  const lines = [];
200	  let n = 0;
201	  const step = (s) => { n += 1; lines.push(`${n}. ${s}`); };
202	
203	  // The item's own label set can be computed exactly, because the item was read
204	  // with its labels. Any OTHER issue's cannot — so that one is emitted as a
205	  // read-modify-write naming only the change, and never as a computed set, which
206	  // would silently drop every label this process never saw.
207	  const own = new Set(labelNames(item));
208	  const foreign = [];
209	  // The body write folds into the item's own `issue_write`, which is one call
210	  // either way. A park never closes, so the step it folds into is the trailing
211	  // label write below.
212	  let newBody = null;
213	
214	  for (const op of convergeOps(item, plan)) {
215	    if (op.kind === 'comment') {
216	      step(`\`add_issue_comment\` — owner \`${owner}\`, repo \`${name}\`, issue_number \`${op.issue}\`, body exactly:\n\n<<<BODY\n${op.body}\n>>>END\n`);
217	    } else if (op.kind === 'record') {
218	      step(`Output this line, on its own, in your reply. Nothing else emits it, and the usage census is read from your transcript:\n\n    ${op.line}\n`);
219	    } else if (op.kind === 'removeLabel' || op.kind === 'addLabel') {
220	      if (op.issue === item.number) {
221	        if (op.kind === 'removeLabel') own.delete(op.name); else own.add(op.name);
222	      } else {
223	        foreign.push(op);
224	      }
225	    } else if (op.kind === 'setBody' && op.issue === item.number) {
226	      newBody = op.body;
227	    } else if (op.kind === 'close') {
228	      step(`\`issue_write\` — method \`update\`, owner \`${owner}\`, repo \`${name}\`, issue_number \`${op.issue}\`,`
229	        + ` labels \`${JSON.stringify([...own])}\`, state \`closed\`, state_reason \`${op.stateReason}\``);
230	      own.clear();
231	    }
232	  }
233	  // A park never closed, so its label write is still owed.
234	  if (own.size) {
235	    step(`\`issue_write\` — method \`update\`, owner \`${owner}\`, repo \`${name}\`, issue_number \`${item.number}\`,`
236	      + ` labels \`${JSON.stringify([...own])}\``
237	      + (newBody === null ? '' : `, body exactly:\n\n<<<BODY\n${newBody}\n>>>END\n`));
238	  }
239	  for (const op of foreign) {
240	    step(`On #${op.issue}: ${op.kind === 'addLabel' ? 'ADD' : 'REMOVE'} the label \`${op.name}\`.`
241	      + ` Read that issue's current labels first and write them back with only this one change —`
242	      + ` \`issue_write\` replaces the whole set, and this process never saw the rest.`);
243	  }
244	  return lines.join('\n');
245	}
246	
247	async function main() {
248	  const plan = parseArgs(process.argv.slice(2));
249	  if (plan.error) {
250	    console.error(`converge-item: ${plan.error}`);
251	    process.exit(2);
252	  }
253	
254	  // The repo this item lives in. `--repo` is what instructions.md passes; the two
255	  // environment names answer for a session whose harness sets one of them.
